BEGIN TRANSACTION;

PRAGMA foreign_keys = ON;

DROP TABLE IF EXISTS almanac_nutation_term;
DROP TABLE IF EXISTS almanac_nutation_model;
DROP TABLE IF EXISTS almanac_constant;
DROP TABLE IF EXISTS almanac_lunar_latitude_term;
DROP TABLE IF EXISTS almanac_lunar_longitude_radius_term;
DROP TABLE IF EXISTS almanac_lunar_correction_model;
DROP TABLE IF EXISTS almanac_lunar_fundamentals_model;
DROP TABLE IF EXISTS almanac_lunar_fundamental_coeff;
DROP TABLE IF EXISTS almanac_orbital_elements_model;
DROP TABLE IF EXISTS almanac_keplerian_model;
DROP TABLE IF EXISTS almanac_fixed_equatorial_model;
DROP TABLE IF EXISTS almanac_body;

CREATE TABLE almanac_body (
    body_code TEXT PRIMARY KEY NOT NULL,
    display_name TEXT NOT NULL,
    body_kind TEXT NOT NULL CHECK (body_kind IN ('star', 'planet', 'sun', 'moon')),
    model_kind TEXT NOT NULL CHECK (model_kind IN ('fixed_equatorial', 'keplerian', 'orbital_elements', 'lunar_keplerian')),
    brightness_model TEXT NOT NULL DEFAULT 'none'
        CHECK (brightness_model IN ('none', 'catalogued', 'sun_distance', 'planetary_phase', 'lunar_phase')),
    magnitude_constant REAL,
    magnitude_linear REAL,
    magnitude_quadratic REAL,
    magnitude_cubic REAL,
    magnitude_quartic REAL,
    sort_order INTEGER NOT NULL,
    enabled INTEGER NOT NULL DEFAULT 1 CHECK (enabled IN (0, 1))
);

CREATE TABLE almanac_fixed_equatorial_model (
    body_code TEXT PRIMARY KEY NOT NULL REFERENCES almanac_body(body_code) ON DELETE CASCADE,
    epoch_jd REAL NOT NULL DEFAULT 2451545.0,
    ra_hours REAL NOT NULL,
    dec_degrees REAL NOT NULL,
    pm_ra_mas_per_year REAL NOT NULL DEFAULT 0.0,
    pm_dec_mas_per_year REAL NOT NULL DEFAULT 0.0
);

CREATE TABLE almanac_keplerian_model (
    body_code TEXT PRIMARY KEY NOT NULL REFERENCES almanac_body(body_code) ON DELETE CASCADE,
    epoch_jd REAL NOT NULL DEFAULT 2451543.5,
    N0 REAL NOT NULL,
    N_dot REAL NOT NULL,
    i0 REAL NOT NULL,
    i_dot REAL NOT NULL,
    w0 REAL NOT NULL,
    w_dot REAL NOT NULL,
    a0 REAL NOT NULL,
    a_dot REAL NOT NULL,
    e0 REAL NOT NULL,
    e_dot REAL NOT NULL,
    M0 REAL NOT NULL,
    M_dot REAL NOT NULL
);

CREATE TABLE almanac_lunar_fundamental_coeff (
    term_code TEXT PRIMARY KEY NOT NULL,
    c0 REAL NOT NULL,
    c1 REAL NOT NULL,
    c2 REAL NOT NULL DEFAULT 0.0,
    c3 REAL NOT NULL DEFAULT 0.0,
    c4 REAL NOT NULL DEFAULT 0.0,
    sort_order INTEGER NOT NULL
);

CREATE TABLE almanac_lunar_fundamentals_model (
    model_id INTEGER PRIMARY KEY,
    body_code TEXT NOT NULL,
    start_jd REAL NOT NULL,
    end_jd REAL NOT NULL,
    reference_jd REAL NOT NULL,
    span_days REAL NOT NULL,
    Lp_c0 REAL NOT NULL,
    Lp_c1 REAL NOT NULL,
    Lp_c2 REAL NOT NULL,
    Lp_c3 REAL NOT NULL,
    Lp_c4 REAL NOT NULL,
    D_c0 REAL NOT NULL,
    D_c1 REAL NOT NULL,
    D_c2 REAL NOT NULL,
    D_c3 REAL NOT NULL,
    D_c4 REAL NOT NULL,
    M_c0 REAL NOT NULL,
    M_c1 REAL NOT NULL,
    M_c2 REAL NOT NULL,
    M_c3 REAL NOT NULL,
    M_c4 REAL NOT NULL,
    Mp_c0 REAL NOT NULL,
    Mp_c1 REAL NOT NULL,
    Mp_c2 REAL NOT NULL,
    Mp_c3 REAL NOT NULL,
    Mp_c4 REAL NOT NULL,
    F_c0 REAL NOT NULL,
    F_c1 REAL NOT NULL,
    F_c2 REAL NOT NULL,
    F_c3 REAL NOT NULL,
    F_c4 REAL NOT NULL,
    sort_order INTEGER NOT NULL,
    FOREIGN KEY (body_code) REFERENCES almanac_body(body_code)
);

CREATE TABLE almanac_lunar_longitude_radius_term (
    term_id INTEGER PRIMARY KEY,
    multiplier_D INTEGER NOT NULL DEFAULT 0,
    multiplier_M INTEGER NOT NULL DEFAULT 0,
    multiplier_Mp INTEGER NOT NULL DEFAULT 0,
    multiplier_F INTEGER NOT NULL DEFAULT 0,
    longitude_coeff_microdeg REAL NOT NULL DEFAULT 0.0,
    radius_coeff_millikm REAL NOT NULL DEFAULT 0.0,
    sort_order INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE almanac_lunar_latitude_term (
    term_id INTEGER PRIMARY KEY,
    multiplier_D INTEGER NOT NULL DEFAULT 0,
    multiplier_M INTEGER NOT NULL DEFAULT 0,
    multiplier_Mp INTEGER NOT NULL DEFAULT 0,
    multiplier_F INTEGER NOT NULL DEFAULT 0,
    latitude_coeff_microdeg REAL NOT NULL DEFAULT 0.0,
    sort_order INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE almanac_lunar_correction_model (
    model_id INTEGER PRIMARY KEY,
    body_code TEXT NOT NULL,
    start_jd REAL NOT NULL,
    end_jd REAL NOT NULL,
    reference_jd REAL NOT NULL,
    span_days REAL NOT NULL,
    lon_c0_deg REAL NOT NULL,
    lon_c1_deg REAL NOT NULL,
    lon_c2_deg REAL NOT NULL,
    lon_c3_deg REAL NOT NULL,
    lon_c4_deg REAL NOT NULL,
    lon_c5_deg REAL NOT NULL,
    lon_c6_deg REAL NOT NULL,
    lon_c7_deg REAL NOT NULL,
    lat_c0_deg REAL NOT NULL,
    lat_c1_deg REAL NOT NULL,
    lat_c2_deg REAL NOT NULL,
    lat_c3_deg REAL NOT NULL,
    lat_c4_deg REAL NOT NULL,
    lat_c5_deg REAL NOT NULL,
    lat_c6_deg REAL NOT NULL,
    lat_c7_deg REAL NOT NULL,
    radius_c0_km REAL NOT NULL,
    radius_c1_km REAL NOT NULL,
    radius_c2_km REAL NOT NULL,
    radius_c3_km REAL NOT NULL,
    radius_c4_km REAL NOT NULL,
    radius_c5_km REAL NOT NULL,
    radius_c6_km REAL NOT NULL,
    radius_c7_km REAL NOT NULL,
    sort_order INTEGER NOT NULL,
    FOREIGN KEY (body_code) REFERENCES almanac_body(body_code)
);

CREATE TABLE almanac_orbital_elements_model (
    model_id INTEGER PRIMARY KEY,
    body_code TEXT NOT NULL REFERENCES almanac_body(body_code) ON DELETE CASCADE,
    start_jd REAL NOT NULL,
    end_jd REAL NOT NULL,
    reference_jd REAL NOT NULL,
    span_days REAL NOT NULL CHECK (span_days > 0.0),
    Omega_c0 REAL NOT NULL,
    Omega_c1 REAL NOT NULL DEFAULT 0.0,
    Omega_c2 REAL NOT NULL DEFAULT 0.0,
    i_c0 REAL NOT NULL,
    i_c1 REAL NOT NULL DEFAULT 0.0,
    i_c2 REAL NOT NULL DEFAULT 0.0,
    varpi_c0 REAL NOT NULL,
    varpi_c1 REAL NOT NULL DEFAULT 0.0,
    varpi_c2 REAL NOT NULL DEFAULT 0.0,
    a_c0 REAL NOT NULL,
    a_c1 REAL NOT NULL DEFAULT 0.0,
    a_c2 REAL NOT NULL DEFAULT 0.0,
    e_c0 REAL NOT NULL,
    e_c1 REAL NOT NULL DEFAULT 0.0,
    e_c2 REAL NOT NULL DEFAULT 0.0,
    L_c0 REAL NOT NULL,
    L_c1 REAL NOT NULL DEFAULT 0.0,
    L_c2 REAL NOT NULL DEFAULT 0.0,
    CHECK (end_jd > start_jd)
);

CREATE TABLE almanac_constant (
    constant_name TEXT PRIMARY KEY NOT NULL,
    constant_value REAL NOT NULL
);

CREATE TABLE almanac_nutation_term (
    term_id INTEGER PRIMARY KEY,
    multiplier_L INTEGER NOT NULL DEFAULT 0,
    multiplier_Lprime INTEGER NOT NULL DEFAULT 0,
    multiplier_omega INTEGER NOT NULL DEFAULT 0,
    sin_coeff_arcsec REAL NOT NULL DEFAULT 0.0,
    cos_coeff_arcsec REAL NOT NULL DEFAULT 0.0,
    sort_order INTEGER NOT NULL DEFAULT 0
);

CREATE TABLE almanac_nutation_model (
    model_id INTEGER PRIMARY KEY,
    start_jd REAL NOT NULL,
    end_jd REAL NOT NULL,
    reference_jd REAL NOT NULL,
    span_days REAL NOT NULL CHECK (span_days > 0.0),
    dpsi_c0_rad REAL NOT NULL,
    dpsi_c1_rad REAL NOT NULL,
    dpsi_c2_rad REAL NOT NULL,
    dpsi_c3_rad REAL NOT NULL,
    dpsi_c4_rad REAL NOT NULL,
    dpsi_c5_rad REAL NOT NULL,
    dpsi_c6_rad REAL NOT NULL,
    dpsi_c7_rad REAL NOT NULL,
    deps_c0_rad REAL NOT NULL,
    deps_c1_rad REAL NOT NULL,
    deps_c2_rad REAL NOT NULL,
    deps_c3_rad REAL NOT NULL,
    deps_c4_rad REAL NOT NULL,
    deps_c5_rad REAL NOT NULL,
    deps_c6_rad REAL NOT NULL,
    deps_c7_rad REAL NOT NULL,
    sort_order INTEGER NOT NULL,
    CHECK (end_jd > start_jd)
);

CREATE INDEX idx_almanac_orbital_elements_lookup
    ON almanac_orbital_elements_model(body_code, start_jd, end_jd);



